cd /app; cat > /tmp/solve.py <<'EOF'
import csv, json, collections, sys
from datetime import datetime, timezone
def rd(p): return list(csv.DictReader(open(p)))
def T(s): return datetime.strptime(s,'%Y-%m-%dT%H:%M:%SZ').replace(tzinfo=timezone.utc)
plan={r['run_id']:r for r in rd('plan.csv')}
lm={r['run_id']:r for r in rd('launch_log.csv')}
E={r['run_id']:float(r['pass_rate']) for r in rd('eval_results.csv')}
R={r['run_id']:T(r['finished_at']) for r in rd('runtime.csv')}
RL={r['run_id']:r for r in rd('retention_log.csv')}
suites=json.load(open('suites.json'))
pol=json.load(open('retention_policy.json'))['versions']
def floor(t):
    for v in pol:
        if T(v['from'])<=t<T(v['to']): return v['floor']
rec={}
for i in range(4):
    for r in rd(f'recovered/shard_0{i}.csv'): rec[r['run_id']]=round(float(r['pass_rate_pct'])/100,4)
L=set(lm)
val={**E,**{k:v for k,v in rec.items() if k in L}}
free=sorted(L-set(val))
MODEL=sys.argv[1] if len(sys.argv)>1 else 'A'
lo={};hi={}
for k in free:
    s=suites[plan[k]['suite']]
    l=s['random_guess'] if s['scoring']=='raw' else 0.0
    h=1.0
    if k in RL and RL[k]['reason']=='below_retention_floor':
        h=min(h,floor(T(RL[k]['dropped_at'])))
    elif MODEL=='B':
        l=max(l,floor(R[k]))
    lo[k]=l;hi[k]=h
dig={r['date']:float(r['sum_pass_rate']) for r in rd('daily_digest.csv')}
byday=collections.defaultdict(list)
for k in L: byday[R[k].strftime('%Y-%m-%d')].append(k)
resid={}
for d,ks in byday.items():
    resid[d]=round(dig[d]-sum(val[k] for k in ks if k in val),4)
    fr=[k for k in ks if k not in val]
    assert sum(lo[k] for k in fr)-1e-9<=resid[d]<=sum(hi[k] for k in fr)+1e-9,(d,resid[d],sum(lo[k] for k in fr),sum(hi[k] for k in fr))
def cellruns(c):
    return [k for k in L if all(plan[k][f]==c[f] for f in ('suite','curriculum','retrieval','decoder'))]
def optimize(coef,sign):
    # maximize sign*sum coef[k]*x_k over free k subject to bounds & per-day sums; known contribute constants
    tot=sum(coef[k]*val[k] for k in coef if k in val)
    fd=collections.defaultdict(list)
    for k in free: fd[R[k].strftime('%Y-%m-%d')].append(k)
    for d,ks in fd.items():
        cs={k:sign*coef.get(k,0.0) for k in ks}
        if all(c==0 for c in cs.values()): continue
        x={k:lo[k] for k in ks}; rem=resid[d]-sum(x.values())
        for k in sorted(ks,key=lambda k:-cs[k]):
            add=min(hi[k]-lo[k],rem); x[k]+=add; rem-=add
        assert rem<1e-9
        tot+=sum(coef.get(k,0.0)*x[k] for k in ks)
    return tot
def interval(coef):
    return (-optimize(coef,-1),optimize(coef,1))
Q=json.load(open('queries.json'))
out={'cells':{},'contrasts':{},'decisions':{}}
def cellcoef(c,scale):
    ks=cellruns(c); return {k:scale/len(ks) for k in ks},len(ks),sum(1 for k in ks if k in free)
for q in Q['cells']:
    coef,n,nf=cellcoef(q['cell'],1.0); lo_,hi_=interval(coef)
    out['cells'][q['id']]={'lo':round(lo_,6),'hi':round(hi_,6)}; print(q['id'],n,nf,'%.4f %.4f'%(lo_,hi_))
def contrast(q):
    c1,n1,f1=cellcoef(q['to'],1.0); c0,n0,f0=cellcoef(q['from'],-1.0)
    coef=dict(c1)
    for k,v in c0.items(): coef[k]=coef.get(k,0)+v
    return interval(coef),(n1,f1,n0,f0)
for q in Q['contrasts']:
    (lo_,hi_),info=contrast(q); out['contrasts'][q['id']]={'lo':round(lo_,6),'hi':round(hi_,6)}; print(q['id'],info,'%.4f %.4f'%(lo_,hi_))
for q in Q['decisions']:
    (lo_,hi_),info=contrast(q); m=q['margin']
    ans='yes' if lo_>m+1e-12 else ('no' if hi_<=m+1e-12 else 'cannot_tell')
    out['decisions'][q['id']]=ans; print(q['id'],info,'%.4f %.4f'%(lo_,hi_),m,ans)
json.dump(out,open(f'/tmp/answers_{MODEL}.json','w'),indent=1)
EOF
echo "=== MODEL A"; python3 /tmp/solve.py A; echo "=== MODEL B"; python3 /tmp/solve.py B
